import{_ as t,o,c as d,a3 as i}from"./chunks/framework.vDgOMd_y.js";const m=JSON.parse('{"title":"Environment variables","description":"","frontmatter":{},"headers":[],"relativePath":"en/configuration/env-vars.md","filePath":"en/configuration/env-vars.md"}'),a={name:"en/configuration/env-vars.md"};function c(s,e,n,r,l,h){return o(),d("div",null,[...e[0]||(e[0]=[i('<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /kimiteam/docs/en/configuration/env-vars.md for this page in Markdown format</div><h1 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment variables&quot;">​</a></h1><p>Kimi Code CLI uses environment variables to control a small number of runtime behaviors — relocating the data directory, turning off telemetry, and temporarily switching models without touching the config file.</p><div class="warning custom-block"><p class="custom-block-title">Important: API keys are not configured here</p><p>Credential variables such as <code>KIMI_API_KEY</code>, <code>ANTHROPIC_API_KEY</code>, and <code>OPENAI_API_KEY</code> are <strong>not</strong> read automatically from shell environment variables. Running <code>export KIMI_API_KEY=xxx</code> in the terminal does not give any provider its key — they must be written in <code>config.toml</code> under <code>[providers.&lt;name&gt;]</code> or the <code>[providers.&lt;name&gt;.env]</code> sub-table.</p><p>The only exception is the <code>KIMI_MODEL_*</code> family, which is an explicit channel that <em>does</em> read credentials from the shell — see <a href="#define-a-model-from-environment-variables-kimi-model">Define a model from environment variables</a>.</p><p>For background, see <a href="./overrides.html#provider-credentials">Config overrides: provider credentials</a>.</p></div><h2 id="core-paths" tabindex="-1">Core paths <a class="header-anchor" href="#core-paths" aria-label="Permalink to &quot;Core paths&quot;">​</a></h2><h3 id="kimi-code-home" tabindex="-1"><code>KIMI_CODE_HOME</code> <a class="header-anchor" href="#kimi-code-home" aria-label="Permalink to &quot;`KIMI_CODE_HOME`&quot;">​</a></h3><p>Overrides the data root directory; the default is <code>~/.kimi-code</code>. Once set, the config file, sessions, logs, OAuth credentials, and all other data land under the new path:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> KIMI_CODE_HOME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/path/to/custom/kimi-code&quot;</span></span></code></pre></div><blockquote><p>Make sure the directory is writable. Multiple <code>kimi</code> instances sharing the same <code>KIMI_CODE_HOME</code> will share config and credential files.</p></blockquote><p>For the complete data directory structure, see <a href="./data-locations.html">Data locations</a>.</p><h3 id="kimi-disable-telemetry" tabindex="-1"><code>KIMI_DISABLE_TELEMETRY</code> <a class="header-anchor" href="#kimi-disable-telemetry" aria-label="Permalink to &quot;`KIMI_DISABLE_TELEMETRY`&quot;">​</a></h3><p>Set to <code>1</code> to turn off anonymous telemetry reporting (also accepts <code>true</code>, <code>yes</code>, <code>y</code>, case-insensitive):</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> KIMI_DISABLE_TELEMETRY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span></code></pre></div><h3 id="kimi-model-family" tabindex="-1"><code>KIMI_MODEL_*</code> family <a class="header-anchor" href="#kimi-model-family" aria-label="Permalink to &quot;`KIMI_MODEL_*` family&quot;">​</a></h3><p>Switch models temporarily without modifying <code>config.toml</code> — when <code>KIMI_MODEL_NAME</code> is set, the CLI synthesizes a temporary provider in memory; the change does not persist after restart. See <a href="#define-a-model-from-environment-variables-kimi-model">Define a model from environment variables</a>.</p><h2 id="provider-credential-key-names-written-in-config-toml" tabindex="-1">Provider credential key names (written in config.toml) <a class="header-anchor" href="#provider-credential-key-names-written-in-config-toml" aria-label="Permalink to &quot;Provider credential key names (written in config.toml)&quot;">​</a></h2><p>The key names below are not read directly from the shell — they are key names written inside the <code>[providers.&lt;name&gt;.env]</code> sub-table of <code>config.toml</code>, serving as fallback values for <code>api_key</code> / <code>base_url</code>. The CLI reads only from the config file, not from <code>process.env</code>.</p><p>This design lets you keep familiar key name conventions while centralizing secret management in the config file:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">providers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">env</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">KIMI_API_KEY = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;sk-xxx&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">KIMI_BASE_URL = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://api.moonshot.ai/v1&quot;</span></span></code></pre></div><p>Key names per provider:</p><table tabindex="0"><thead><tr><th>Key</th><th>Applicable provider</th><th>Default</th></tr></thead><tbody><tr><td><code>KIMI_API_KEY</code></td><td>Kimi / Moonshot</td><td>None</td></tr><tr><td><code>KIMI_BASE_URL</code></td><td>Kimi / Moonshot</td><td><code>https://api.moonshot.ai/v1</code></td></tr><tr><td><code>ANTHROPIC_API_KEY</code></td><td>Anthropic</td><td>None</td></tr><tr><td><code>ANTHROPIC_BASE_URL</code></td><td>Anthropic</td><td>Follows Anthropic SDK default</td></tr><tr><td><code>OPENAI_API_KEY</code></td><td>OpenAI (<code>openai</code> and <code>openai_responses</code>)</td><td>None</td></tr><tr><td><code>OPENAI_BASE_URL</code></td><td>OpenAI (<code>openai</code> and <code>openai_responses</code>)</td><td><code>https://api.openai.com/v1</code></td></tr><tr><td><code>GOOGLE_API_KEY</code></td><td>Google GenAI, Vertex AI</td><td>None</td></tr><tr><td><code>VERTEXAI_API_KEY</code></td><td>Vertex AI</td><td>None</td></tr><tr><td><code>GOOGLE_CLOUD_PROJECT</code></td><td>Vertex AI</td><td>None</td></tr><tr><td><code>GOOGLE_CLOUD_LOCATION</code></td><td>Vertex AI</td><td>None</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><code>GOOGLE_APPLICATION_CREDENTIALS</code> (path to a service account JSON file) is the only exception that goes through the system environment variable mechanism — it is read by the Google SDK directly via the standard ADC flow, and the CLI does not participate. All other key names must be placed in the <code>[providers.&lt;name&gt;.env]</code> sub-table to take effect.</p></div><p>For the full provider type and field reference, see <a href="./providers.html">Providers and models</a>.</p><h2 id="oauth-and-managed-services" tabindex="-1">OAuth and managed services <a class="header-anchor" href="#oauth-and-managed-services" aria-label="Permalink to &quot;OAuth and managed services&quot;">​</a></h2><p>This group of variables redirects OAuth authentication and managed service endpoints to a self-hosted or test environment. They are not needed for everyday use.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Purpose</th><th>Default</th></tr></thead><tbody><tr><td><code>KIMI_CODE_OAUTH_HOST</code></td><td>OAuth auth host; highest priority</td><td>Falls back to <code>KIMI_OAUTH_HOST</code> when unset</td></tr><tr><td><code>KIMI_OAUTH_HOST</code></td><td>OAuth auth host; fallback for <code>KIMI_CODE_OAUTH_HOST</code></td><td>Falls back to <code>https://auth.kimi.com</code> when unset</td></tr><tr><td><code>KIMI_CODE_BASE_URL</code></td><td>Managed API base URL used after OAuth login</td><td><code>https://api.kimi.com/coding/v1</code></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><code>KIMI_CODE_BASE_URL</code> (OAuth-managed service, targeting <code>kimi.com</code>) and <code>KIMI_BASE_URL</code> (direct API key connection, targeting <code>moonshot.ai</code>) are two distinct variables. Use each one in its appropriate context.</p></div><h2 id="define-a-model-from-environment-variables-kimi-model" tabindex="-1">Define a model from environment variables (<code>KIMI_MODEL_*</code>) <a class="header-anchor" href="#define-a-model-from-environment-variables-kimi-model" aria-label="Permalink to &quot;Define a model from environment variables (`KIMI_MODEL_*`)&quot;">​</a></h2><p>Want to switch models for testing without touching <code>config.toml</code>? When <code>KIMI_MODEL_NAME</code> is set, the CLI synthesizes a temporary provider and model alias from the <code>KIMI_MODEL_*</code> variables in memory — nothing is written back to the config file. These variables take priority over <code>default_model</code> in <code>config.toml</code>, but the <code>-m &lt;alias&gt;</code> option at startup still has the highest priority.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> KIMI_MODEL_NAME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;kimi-for-coding&quot;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> KIMI_MODEL_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;YOUR_API_KEY&quot;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> KIMI_MODEL_BASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://api.example.com/v1&quot;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> KIMI_MODEL_MAX_CONTEXT_SIZE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;262144&quot;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> KIMI_MODEL_CAPABILITIES</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;image_in,thinking&quot;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span></span></code></pre></div><p>Complete variable list:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Purpose</th><th>Default</th></tr></thead><tbody><tr><td><code>KIMI_MODEL_NAME</code></td><td>Yes (also the enable switch)</td><td>Model id sent to the API</td><td>—</td></tr><tr><td><code>KIMI_MODEL_API_KEY</code></td><td>Yes</td><td>API key</td><td>—</td></tr><tr><td><code>KIMI_MODEL_PROVIDER_TYPE</code></td><td>No</td><td>Provider type: <code>kimi</code>, <code>anthropic</code>, <code>openai</code></td><td><code>kimi</code></td></tr><tr><td><code>KIMI_MODEL_BASE_URL</code></td><td>No</td><td>API base URL</td><td>Each type has its own default</td></tr><tr><td><code>KIMI_MODEL_MAX_CONTEXT_SIZE</code></td><td>No</td><td>Maximum context length (tokens)</td><td><code>262144</code> (256 K)</td></tr><tr><td><code>KIMI_MODEL_CAPABILITIES</code></td><td>No</td><td>Comma-separated capability tags, unioned with auto-detected capabilities</td><td><code>image_in,thinking</code></td></tr><tr><td><code>KIMI_MODEL_DISPLAY_NAME</code></td><td>No</td><td>Name shown in <code>/model</code></td><td>Falls back to <code>KIMI_MODEL_NAME</code></td></tr><tr><td><code>KIMI_MODEL_MAX_OUTPUT_SIZE</code></td><td>No</td><td>Per-request output cap (<code>anthropic</code> only); when set, overrides the built-in Claude ceiling</td><td>Model default</td></tr><tr><td><code>KIMI_MODEL_REASONING_KEY</code></td><td>No</td><td>Reasoning field name override (<code>openai</code> only)</td><td>Auto-detected</td></tr><tr><td><code>KIMI_MODEL_THINKING_EFFORT</code></td><td>No</td><td>Thinking effort level: <code>low</code>/<code>medium</code>/<code>high</code>/<code>xhigh</code>/<code>max</code></td><td>—</td></tr><tr><td><code>KIMI_MODEL_ADAPTIVE_THINKING</code></td><td>No</td><td>Force adaptive thinking on or off (<code>anthropic</code> only)</td><td>Inferred from model name</td></tr></tbody></table><p>If <code>KIMI_MODEL_NAME</code> is set but a required variable is missing, startup fails immediately with a clear error message.</p><h2 id="runtime-switches" tabindex="-1">Runtime switches <a class="header-anchor" href="#runtime-switches" aria-label="Permalink to &quot;Runtime switches&quot;">​</a></h2><p>Switches that control the behavior of subsystems such as telemetry, background tasks, and the plugin marketplace:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Purpose</th><th>Valid values</th></tr></thead><tbody><tr><td><code>KIMI_DISABLE_TELEMETRY</code></td><td>Disable anonymous telemetry reporting</td><td><code>1</code>, <code>true</code>, <code>yes</code>, <code>y</code> (case-insensitive)</td></tr><tr><td><code>KIMI_CODE_BACKGROUND_KEEP_ALIVE_ON_EXIT</code></td><td>Whether to keep background tasks when the session closes; takes higher priority than <code>config.toml</code>. The default is to stop them on exit</td><td>Truthy: <code>1</code>/<code>true</code>/<code>yes</code>/<code>on</code>; falsy: <code>0</code>/<code>false</code>/<code>no</code>/<code>off</code></td></tr><tr><td><code>KIMI_CODE_BACKGROUND_MAX_RUNNING_TASKS</code></td><td>Cap on concurrently running background tasks; takes higher priority than <code>[background] max_running_tasks</code> in <code>config.toml</code> (unset means no cap)</td><td>Positive integer; invalid values are ignored</td></tr><tr><td><code>KIMI_IMAGE_MAX_EDGE_PX</code></td><td>Longest-edge ceiling (px) for image compression; takes higher priority than <code>[image] max_edge_px</code> in <code>config.toml</code> (default <code>2000</code>)</td><td>Positive integer; invalid values are ignored</td></tr><tr><td><code>KIMI_IMAGE_READ_BYTE_BUDGET</code></td><td>Per-image byte budget for model-initiated image reads (<code>ReadMediaFile</code> default reads); takes higher priority than <code>[image] read_byte_budget</code> in <code>config.toml</code> (default <code>262144</code>, i.e. 256 KB)</td><td>Positive integer; invalid values are ignored</td></tr><tr><td><code>KIMI_CODE_PLUGIN_MARKETPLACE_URL</code></td><td>Override the plugin marketplace JSON loaded by <code>/plugins</code>; useful for dev loopback servers, staging CDN files, or alternate marketplace directories</td><td><code>https://code.kimi.com/kimi-code/plugins/marketplace.json</code>; also accepts <code>http://</code>, <code>file://</code> URLs, and local paths</td></tr><tr><td><code>KIMI_CODE_AGENT_SWARM_MAX_CONCURRENCY</code></td><td>Session-level subagent concurrency cap; highest priority (env &gt; runtime <code>TeamConcurrency</code> &gt; config <code>max_concurrency</code>); leave unset for no cap</td><td>Positive integer; invalid values are ignored with a warning, falling back to the next priority level</td></tr><tr><td><code>KIMI_SUBAGENT_TIMEOUT_MS</code></td><td>Maximum wall-clock time (ms) a single subagent (<code>Agent</code> / <code>AgentSwarm</code>) may run; takes higher priority than <code>[subagent] timeout_ms</code> in <code>config.toml</code> (default <code>7200000</code>, i.e. 2 hours)</td><td>Positive integer; invalid values fall back to the config or default</td></tr><tr><td><code>KIMI_CODE_IDENTITY_NAME</code></td><td>Display name the agent calls itself in the system prompt; takes higher priority than <code>[identity] name</code> in <code>config.toml</code> and is never written back to it</td><td>Any non-empty string; blank values read as unset</td></tr><tr><td><code>KIMI_CODE_IDENTITY_SLUG</code></td><td>Protocol identifier for the <code>User-Agent</code> product token sent to third-party providers and the MCP client name; takes higher priority than <code>[identity] slug</code>. Derived from the name when unset</td><td>Any non-empty string; normalized to lowercase with non-alphanumeric runs folded to <code>-</code></td></tr><tr><td><code>KIMI_CODE_BUILTIN_PRODUCT_SKILLS</code></td><td>Whether the built-in skills documenting Kimi Code itself are offered to the model; takes higher priority than <code>builtin_product_skills</code> in <code>config.toml</code> (default enabled)</td><td>Truthy: <code>1</code>/<code>true</code>/<code>yes</code>/<code>on</code>; falsy: <code>0</code>/<code>false</code>/<code>no</code>/<code>off</code></td></tr><tr><td><code>KIMI_CODE_EXPERIMENTAL_SECONDARY_MODEL</code></td><td>Enable the experimental secondary-model feature in every launch mode, including the interactive TUI; the master <code>KIMI_CODE_EXPERIMENTAL_FLAG=1</code> also enables it</td><td>Truthy: <code>1</code>/<code>true</code>/<code>yes</code>/<code>on</code>; falsy: <code>0</code>/<code>false</code>/<code>no</code>/<code>off</code></td></tr><tr><td><code>KIMI_SECONDARY_MODEL</code></td><td>Secondary model; takes higher priority than <a href="./config-files.html#secondary-model"><code>[secondary_model] model</code></a> in <code>config.toml</code>. When the secondary-model experiment is enabled, newly spawned subagents (<code>Agent</code> / <code>AgentSwarm</code>) bind to it by default instead of inheriting the main agent&#39;s model</td><td>The alias of a configured <code>[models]</code> entry, e.g. <code>kimi-code/kimi-k2.5</code>; blank values are ignored</td></tr><tr><td><code>KIMI_SECONDARY_EFFORT</code></td><td>Thinking effort for the secondary model; takes higher priority than <code>[secondary_model] default_effort</code> in <code>config.toml</code> and applies only when both the model and its experiment are enabled</td><td>An effort value, e.g. <code>low</code>; blank values are ignored</td></tr><tr><td><code>KIMI_MCP_STARTUP_TIMEOUT_MS</code></td><td>Global default connection timeout (ms) for all MCP servers; takes higher priority than <code>[mcp] startup_timeout_ms</code> in <code>config.toml</code>, but a per-server <code>startupTimeoutMs</code> in <code>mcp.json</code> still wins (default <code>30000</code>)</td><td>Integer from <code>1</code> to <code>2147483647</code>; invalid values are ignored</td></tr><tr><td><code>KIMI_MCP_TOOL_TIMEOUT_MS</code></td><td>Global default single tool-call timeout (ms) for all MCP servers; takes higher priority than <code>[mcp] tool_timeout_ms</code> in <code>config.toml</code>, but a per-server <code>toolTimeoutMs</code> in <code>mcp.json</code> still wins (default <code>60000</code>)</td><td>Integer from <code>1</code> to <code>2147483647</code>; invalid values are ignored</td></tr><tr><td><code>KIMI_LOOP_MAX_STEPS_PER_TURN</code></td><td>Maximum Agent steps per turn; takes higher priority than <code>[loop_control] max_steps_per_turn</code> in <code>config.toml</code> (unset or <code>0</code> means unlimited)</td><td>Non-negative integer; invalid values are ignored</td></tr><tr><td><code>KIMI_LOOP_MAX_ATTEMPTS_PER_STEP</code></td><td>Maximum total attempts for a failing step (including the initial attempt); takes higher priority than <code>[loop_control] max_attempts_per_step</code> in <code>config.toml</code> (default <code>10</code>). The deprecated <code>KIMI_LOOP_MAX_RETRIES_PER_STEP</code> is still honored with a warning when this variable is unset</td><td>Non-negative integer; invalid values are ignored</td></tr><tr><td><code>KIMI_TOKEN_COUNTING_STRATEGY</code></td><td>Which context token count is reported externally (the context-size display); takes higher priority than <code>[token_counting] strategy</code> in <code>config.toml</code> (default <code>measured+estimated</code>)</td><td><code>measured+estimated</code>, <code>measured</code>, <code>estimated</code> (case-insensitive); invalid values are ignored</td></tr><tr><td><code>KIMI_WEB_SEARCH_BASE_URL</code></td><td>API URL of the web search (<code>WebSearch</code>) service; takes higher priority than <code>[services.moonshot_search] base_url</code> in <code>config.toml</code>, and enables the service without that config section. Persisted credentials and custom headers are not forwarded to an env-selected endpoint</td><td>Non-blank string; blank values are ignored</td></tr><tr><td><code>KIMI_WEB_SEARCH_API_KEY</code></td><td>API key of the web search (<code>WebSearch</code>) service; replaces both the configured API key and OAuth credential when set</td><td>Non-blank string; blank values are ignored</td></tr><tr><td><code>KIMI_WEB_FETCH_BASE_URL</code></td><td>API URL of the web fetch (<code>FetchURL</code>) service; takes higher priority than <code>[services.moonshot_fetch] base_url</code>. Persisted credentials and custom headers are not forwarded to an env-selected endpoint. Without an env or config endpoint, signed-in users try the managed Kimi OAuth fetch service before direct local requests</td><td>Non-blank string; blank values are ignored</td></tr><tr><td><code>KIMI_WEB_FETCH_API_KEY</code></td><td>API key of the web fetch (<code>FetchURL</code>) service; replaces both the configured API key and OAuth credential when set</td><td>Non-blank string; blank values are ignored</td></tr><tr><td><code>KIMI_CODE_EXPERIMENTAL_FLAG</code></td><td>Enable all registered experimental features for this process; it does not select the agent engine</td><td><code>1</code>, <code>true</code>, <code>yes</code>, <code>on</code></td></tr><tr><td><code>KIMI_CODE_LEGACY_FLAG</code></td><td>Use the legacy <code>agent-core</code> engine for <code>kimi</code>, <code>kimi -p</code>, <code>kimi doctor</code>, <code>kimi acp</code>, <code>kimi export</code>, and <code>kimi provider</code>; these commands use <code>agent-core-v2</code> by default</td><td><code>1</code>, <code>true</code>, <code>yes</code>, <code>on</code></td></tr><tr><td><code>KIMI_SHELL_PATH</code></td><td>Override the Git Bash path on Windows (used when auto-detection fails)</td><td>Absolute path</td></tr><tr><td><code>KIMI_MODEL_MAX_COMPLETION_TOKENS</code></td><td>Hard cap on <code>max_completion_tokens</code> per LLM step; applies to the <code>kimi</code> provider only</td><td>Positive integer; <code>0</code> or negative disables clamping</td></tr><tr><td><code>KIMI_MODEL_TEMPERATURE</code></td><td>Sampling temperature for every request; applies to the <code>kimi</code> provider only (global — independent of <code>KIMI_MODEL_NAME</code>)</td><td>Number, e.g. <code>0.3</code></td></tr><tr><td><code>KIMI_MODEL_TOP_P</code></td><td>Nucleus-sampling <code>top_p</code> for every request; applies to the <code>kimi</code> provider only (global)</td><td>Number, e.g. <code>0.95</code></td></tr><tr><td><code>KIMI_MODEL_THINKING_EFFORT</code></td><td>Force a specific thinking effort on the wire (<code>thinking.effort</code>), bypassing the model&#39;s declared <code>support_efforts</code>; applies to the <code>kimi</code> provider only, and only while Thinking is on</td><td>An effort value, e.g. <code>max</code></td></tr><tr><td><code>KIMI_MODEL_THINKING_KEEP</code></td><td>Preserved-thinking passthrough; on <code>kimi</code> sent as <code>thinking.keep</code>, on <code>anthropic</code> (Claude and Kimi&#39;s Anthropic-compatible mode) sent as a <code>context_management</code> <code>clear_thinking_20251015</code> edit (enabling keep routes Anthropic requests to the beta Messages API); overrides <code>[thinking] keep</code> (which defaults to <code>&quot;all&quot;</code>); only injected while Thinking is on</td><td>A value the API accepts, e.g. <code>all</code>; an off-value (<code>false</code>/<code>0</code>/<code>no</code>/<code>off</code>/<code>none</code>/<code>null</code>) disables it</td></tr><tr><td><code>KIMI_CODE_NO_AUTO_UPDATE</code></td><td>Fully disable the update preflight — no check, background install, or prompt. Legacy alias <code>KIMI_CLI_NO_AUTO_UPDATE</code> is also honored</td><td>Truthy: <code>1</code>/<code>true</code>/<code>yes</code>/<code>on</code></td></tr><tr><td><code>KIMI_DISABLE_CRON</code></td><td>Disable the scheduled-task tool (<code>CronCreate</code> rejects new schedules; existing tasks do not fire)</td><td><code>1</code> to disable</td></tr></tbody></table><p>The three <code>KIMI_CODE_IDENTITY_*</code> / <code>KIMI_CODE_BUILTIN_PRODUCT_SKILLS</code> variables are read by the default <code>agent-core-v2</code> engine. The legacy <code>kimi</code> / <code>kimi -p</code> path selected with <code>KIMI_CODE_LEGACY_FLAG=1</code> ignores them.</p><h2 id="diagnostic-logs" tabindex="-1">Diagnostic logs <a class="header-anchor" href="#diagnostic-logs" aria-label="Permalink to &quot;Diagnostic logs&quot;">​</a></h2><p>These variables control log level and file rotation, read once at process startup:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Purpose</th><th>Default</th></tr></thead><tbody><tr><td><code>KIMI_LOG_LEVEL</code></td><td>Log level: <code>off</code>, <code>error</code>, <code>warn</code>, <code>info</code>, <code>debug</code></td><td><code>info</code></td></tr><tr><td><code>KIMI_LOG_GLOBAL_MAX_BYTES</code></td><td>Maximum bytes per global log file</td><td><code>6291456</code> (6 MB)</td></tr><tr><td><code>KIMI_LOG_GLOBAL_FILES</code></td><td>Number of global log files to retain</td><td><code>5</code></td></tr><tr><td><code>KIMI_LOG_SESSION_MAX_BYTES</code></td><td>Maximum bytes per session log file</td><td><code>5242880</code> (5 MB)</td></tr><tr><td><code>KIMI_LOG_SESSION_FILES</code></td><td>Number of session log files to retain</td><td><code>3</code></td></tr></tbody></table><h2 id="system-environment-variables" tabindex="-1">System environment variables <a class="header-anchor" href="#system-environment-variables" aria-label="Permalink to &quot;System environment variables&quot;">​</a></h2><p>The CLI also reads several standard system variables to detect the runtime environment; it does not modify them:</p><ul><li><code>HOME</code>: used to resolve the default data path</li><li><code>VISUAL</code>, <code>EDITOR</code>: external editor command (<code>VISUAL</code> takes precedence)</li><li><code>PATH</code>: used to locate dependencies such as <code>rg</code>, <code>fd</code>, <code>fdfind</code>, and <code>git</code>; on Windows, Git Bash detection checks each <code>git.exe</code> found on <code>PATH</code>, including package-manager shims such as Scoop</li><li><code>NO_COLOR</code>, <code>FORCE_COLOR</code>: control color output (following the <a href="https://no-color.org" target="_blank" rel="noreferrer">no-color.org</a> convention)</li><li><code>CI</code>: when non-empty and not <code>&quot;0&quot;</code>, disables theme detection and falls back to the dark theme</li><li><code>TERM_PROGRAM</code>, <code>TERM</code>, <code>TMUX</code>: detect terminal features and notification support</li><li><code>DISPLAY</code>, <code>WAYLAND_DISPLAY</code>, <code>XDG_SESSION_TYPE</code>: detect Linux graphical sessions (for clipboard and image features)</li><li><code>WSL_DISTRO_NAME</code>, <code>WSLENV</code>: detect WSL for the clipboard PowerShell bridge</li><li><code>LOCALAPPDATA</code>: used on Windows as a fallback when probing for the Git Bash installation path</li></ul><h2 id="http-proxy" tabindex="-1">HTTP proxy <a class="header-anchor" href="#http-proxy" aria-label="Permalink to &quot;HTTP proxy&quot;">​</a></h2><p>Kimi Code honors the standard proxy environment variables for all outbound traffic — model API calls, MCP servers, web tools, telemetry, sign-in, and update checks:</p><ul><li><code>HTTP_PROXY</code> / <code>http_proxy</code>: proxy for <code>http://</code> requests</li><li><code>HTTPS_PROXY</code> / <code>https_proxy</code>: proxy for <code>https://</code> requests</li><li><code>ALL_PROXY</code> / <code>all_proxy</code>: fallback proxy used when the scheme-specific variable is unset; this is where a SOCKS proxy is usually set</li><li><code>NO_PROXY</code> / <code>no_proxy</code>: comma-separated hosts that bypass the proxy</li></ul><p>Both HTTP(S) and SOCKS proxies are supported. A SOCKS proxy is recognized by its scheme — <code>socks5://</code>, <code>socks5h://</code>, <code>socks4://</code>, or <code>socks://</code> (an alias for <code>socks5://</code>) — and is typically set via <code>ALL_PROXY</code> (the form used by tools like Clash and V2RayN). An HTTP(S) proxy takes precedence over <code>ALL_PROXY</code> for HTTP/HTTPS traffic.</p><p>The proxy is applied only when one of these variables is set; otherwise connections are made directly. Loopback hosts (<code>localhost</code>, <code>127.0.0.1</code>, <code>::1</code>) always bypass the proxy, so a local server such as a localhost MCP server keeps working when a proxy is configured — add your own internal hosts to <code>NO_PROXY</code> to exempt them too.</p><p>Stdio MCP servers that run as Node child processes honor <code>HTTP_PROXY</code> / <code>HTTPS_PROXY</code> / <code>NO_PROXY</code> automatically when the child&#39;s Node version supports <code>NODE_USE_ENV_PROXY</code> (Node ≥ 22.21 or ≥ 24.5); SOCKS proxying applies to Kimi Code&#39;s own traffic only.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./overrides.html">Config overrides</a> — how environment variables, CLI options, and the config file interact by priority</li><li><a href="./data-locations.html">Data locations</a> — directory structure affected by <code>KIMI_CODE_HOME</code></li><li><a href="./providers.html">Providers and models</a> — full connection examples per provider type</li></ul>',51)])])}const _=t(a,[["render",c]]);export{m as __pageData,_ as default};
